const express = require('express');
const cors = require('cors');
const app = express();
app.use(cors());
app.use(express.json());

let todos = [];
let currentId = 1;

// GET /todos - list all todos (support ?completed=true/false filter)
app.get('/todos', (req, res) => {
    try {
        const { completed } = req.query;

        if (completed === 'true') {
            const completedTodos = todos.filter(todo => todo.completed);
            res.json({ todos: completedTodos });
            return;
        }

        if (completed === 'false') {
            const pendingTodos = todos.filter(todo => !todo.completed);
            res.json({ todos: pendingTodos });
            return;
        }

        // No filter provided, return all
        res.json({ todos });
    } catch (error) {
        console.error(error);
        res.status(500).json({ error: 'Internal Server Error' });
    }
});

// GET /todos/:id - get single todo
app.get('/todos/:id', (req, res) => {
    try {
        const id = parseInt(req.params.id);

        if (isNaN(id)) {
            return res.status(400).json({ error: 'Invalid ID format' });
        }

        const todoIndex = todos.findIndex(todo => todo.id === id);

        if (todoIndex === -1) {
            return res.status(404).json({ error: 'Todo not found' });
        }

        // Format dates to ISO string
        const formattedTodos = todos.map(todo => ({
            ...todo,
            createdAt: new Date(todo.createdAt).toISOString(),
            updatedAt: new Date(todo.updatedAt).toISOString()
        }));

        res.json(formattedTodos[todoIndex]);
    } catch (error) {
        console.error(error);
        res.status(500).json({ error: 'Internal Server Error' });
    }
});

// POST /todos - create todo
app.post('/todos', (req, res) => {
    try {
        const { title } = req.body;

        // Validate input
        if (!title || typeof title !== 'string') {
            return res.status(400).json({ error: 'Title is required and must be a string' });
        }

        if (title.length < 1 || title.length > 100) {
            return res.status(400).json({ 
                error: `Title length invalid. Must be between 1 and 100 characters` 
            });
        }

        const newTodo = { 
            id: currentId++, 
            title, 
            completed: false,
            createdAt: new Date(),
            updatedAt: new Date()
        };

        todos.push(newTodo);

        res.status(201).json({ todo: newTodo });
    } catch (error) {
        console.error(error);
        res.status(500).json({ error: 'Internal Server Error' });
    }
});

// PUT /todos/:id - update todo
app.put('/todos/:id', (req, res) => {
    try {
        const id = parseInt(req.params.id);

        if (isNaN(id)) {
            return res.status(400).json({ error: 'Invalid ID format' });
        }

        const todoIndex = todos.findIndex(todo => todo.id === id);

        if (todoIndex === -1) {
            return res.status(404).json({ error: 'Todo not found' });
        }

        let updatedData;

        // Validate title field
        if (req.body.title !== undefined) {
            const { title } = req.body;

            if (!title || typeof title !== 'string') {
                return res.status(400).json({ error: 'Title must be a string' });
            }

            if (title.length < 1 || title.length > 100) {
                return res.status(400).json({ 
                    error: `Title length invalid. Must be between 1 and 100 characters` 
                });
            }

            updatedData = { ...updatedData, title };
        }

        // Validate completed field
        if (req.body.completed !== undefined) {
            const { completed } = req.body;

            if (typeof completed !== 'boolean') {
                return res.status(400).json({ error: 'Completed must be a boolean' });
            }

            updatedData = { ...updatedData, completed };
        }

        // If no valid updates, respond with 400
        if (!Object.keys(updatedData || {}).length) {
            return res.status(400).json({ 
                error: 'At least one of title or completed must be provided to update' 
            });
        }

        todos[todoIndex] = {
            ...todos[todoIndex],
            ...(updatedData ? updatedData : { completed: req.body.completed }),
            updatedAt: new Date()
        };

        // Format dates in response
        const formattedTodo = { 
            ...todos[todoIndex], 
            createdAt: new Date(todos[todoIndex].createdAt).toISOString(),
            updatedAt: new Date(todos[todoIndex].updatedAt).toISOString() 
        };

        res.json({ todo: formattedTodo });
    } catch (error) {
        console.error(error);
        res.status(500).json({ error: 'Internal Server Error' });
    }
});

// DELETE /todos/:id - delete todo
app.delete('/todos/:id', (req, res) => {
    try {
        const id = parseInt(req.params.id);

        if (isNaN(id)) {
            return res.status(400).json({ error: 'Invalid ID format' });
        }

        const todoIndex = todos.findIndex(todo => todo.id === id);

        if (todoIndex === -1) {
            return res.status(404).json({ error: 'Todo not found' });
        }

        todos.splice(todoIndex, 1);

        // No content
        res.status(204).send();
    } catch (error) {
        console.error(error);
        res.status(500).json({ error: 'Internal Server Error' });
    }
});

